export interface Env {
  DB: D1Database;
  ASSETS: Fetcher;
  RATE_LIMITER?: RateLimit;
  SESSION_SECRET: string;
  ADMIN_TOKEN?: string;
  SITE_ORIGIN: string;
  /** Web Push (VAPID): raw base64url private scalar and public point, generated by scripts/dev-vars.mjs and setup.mjs. */
  VAPID_PRIVATE?: string;
  VAPID_PUBLIC?: string;
  /** mailto: or https: contact for push services; falls back to SITE_ORIGIN. */
  VAPID_SUBJECT?: string;
}
export interface AuthedVars { userId: string }
export type AppEnv = { Bindings: Env; Variables: AuthedVars };
